function pastCard(item, grade){
  const box=document.createElement('div');box.className='past-card';
  const main=document.createElement('strong');main.textContent=item.id+'　'+item.topic;box.append(main);
  const meta=document.createElement('p');meta.className='caption';
  const playable=!!BYID[item.id]&&!BYID[item.id].provisional;const staged=!!BYID[item.id]?.provisional;
  const g=grade?(grade==='A'?'同じ学習論点の候補':'関連する学習論点')+' ／ ':'';
  meta.textContent=g+'分野：'+item.cat+' ／ '+(playable?'アプリで演習可能':staged?'原文・正答登録済／原図待ち（採点不可）':'主題索引のみ・全文未収録')+(item.figure?' ／ 図表の確認が必要な可能性':'')+((item.scoring||'').includes('除外')?' ／ 公式採点除外（学習素材に限定）':'');box.append(meta);
  if(playable||staged){const b=document.createElement('button');b.className='tiny';b.textContent=staged?'図待ちの原文・正答を見る':'この公式過去問を解く';b.onclick=()=>beginOne(item.id);box.append(b)}
  return box;
}
// v100: CURATED_STUDY_LINKS loaded separately from data/related.js.

function renderPastRelated(id){
 const root=$('pastRelatedList');if(!root)return;root.replaceChildren();
 const verified=(CURATED_STUDY_LINKS[id]||[]).filter(x=>!!BYID[x.id]);
 verified.sort((a,b)=>Number(a.grade!=='same')-Number(b.grade!=='same'));
 const top=verified.slice(0,2);
 const summary=$('relatedDetails')?.querySelector('summary');
 if(summary)summary.textContent=top.length?'別年度の過去問で確認（'+top.length+'問）':'別年度の類題を探す';
 if(top.length){
   let t=document.createElement('p');t.className='caption';t.textContent='下の問題は公式本文・選択肢・正答を確認済み。同じ論点か周辺知識かを区別してあります。';root.append(t);
   for(const entry of top){const q=BYID[entry.id];const block=document.createElement('div');block.className='suggested-sibling';
      let title=document.createElement('strong');title.textContent=(entry.grade==='same'?'同じ学習論点':'関連知識を補強')+'｜'+entry.id;
      let desc=document.createElement('p');desc.textContent=entry.note;
      let btn=document.createElement('button');btn.className='tiny primary';btn.textContent='この公式過去問を解く';btn.onclick=()=>beginOne(q.id);
      block.append(title,desc,btn);root.append(block);
   }
 }else{let p=document.createElement('p');p.className='caption';p.textContent='現在、本文・正答を照合した類題がありません。以下の索引候補を確認できます。';root.append(p)}
 const checked=new Set(top.map(x=>x.id));
 const further=(RELATED_PAST[id]||[]).filter(x=>!checked.has(x.id));
 if(further.length){let details=document.createElement('details');details.className='candidate-details';
  let su=document.createElement('summary');su.textContent='そのほかの候補（主題索引・類似度未確認） '+further.length+'件';details.append(su);
  for(const entry of further.slice(0,8)){const item=PAST_BYID[entry.id];if(!item)continue;
   const card=pastCard(item,entry.grade);details.append(card)}
  root.append(details)}
 let b=document.createElement('button');b.className='secondary tiny';b.textContent='全2,000問の主題を検索';b.onclick=()=>{
   const src=BYID[id]?.stem||'';let cleaned=src.replace(/について.*$/,'').replace(/で正しい.*$/,'').replace(/はどれか.*$/,'').replace(/を.*$/,'');
   $('pastSearch').value=cleaned.length>=2&&cleaned.length<20?cleaned:src.slice(0,12);
   $('pastYear').value='all';$('pastMode').value='all';pastSearch();showView('related');
 };root.append(b);
}
let pastVisible=30;
function pastSearch(reset=true){
 if(reset)pastVisible=30;
 const word=$('pastSearch').value.trim().normalize('NFKC').toLowerCase(),cat=$('pastCat').value,yr=$('pastYear').value,mode=$('pastMode').value;
 const found=PAST_INDEX.filter(x=>(yr==='all'||x.year===Number(yr))&&(cat==='all'||x.cat===cat)&&(mode==='all'||(BYID[x.id]&&!BYID[x.id].provisional))&&(!word||(x.topic+x.id+(((BYID[x.id]||{}).opts||[]).join(' '))).normalize('NFKC').toLowerCase().includes(word)));
 // Prefer a playable official past question when both playable and index-only hits match the same term.
 found.sort((a,b)=>Number(!!BYID[b.id]&&!BYID[b.id].provisional)-Number(!!BYID[a.id]&&!BYID[a.id].provisional)||a.year-b.year||a.id.localeCompare(b.id));
 const playable=found.filter(x=>BYID[x.id]&&!BYID[x.id].provisional).length;
 $('pastSearchCount').textContent='条件に一致：'+found.length+'問（このアプリで解ける'+playable+'問・索引のみ'+(found.length-playable)+'問）／2,000問中　表示：'+Math.min(pastVisible,found.length)+'件';
 const root=$('pastSearchResults');root.replaceChildren();
 for(const x of found.slice(0,pastVisible))root.append(pastCard(x));
 if(pastVisible<found.length){const next=document.createElement('button');next.type='button';next.className='secondary';next.textContent='さらに30件表示（残り'+(found.length-pastVisible)+'問）';next.onclick=()=>{pastVisible+=30;pastSearch(false)};root.append(next)}
 if(!found.length){const p=document.createElement('p');p.className='caption';p.textContent='該当する主題は見つかりませんでした。略語や短いキーワードで再検索してください。';root.append(p)}
}
function pastInit(){for(let y=52;y<=61;y++){let e=document.createElement('option');e.value=String(y);e.textContent='第'+y+'回';$('pastYear').append(e)}
 for(const c of [...new Set(PAST_INDEX.map(x=>x.cat))].sort()){let e=document.createElement('option');e.value=c;e.textContent=c;$('pastCat').append(e)}
 for(const id of ['pastSearch','pastYear','pastCat','pastMode'])$(id).addEventListener(id==='pastSearch'?'input':'change',pastSearch);
 pastSearch();
}

