function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function score(q){let h=allOf(q.id);if(!h.length)return -1;let last=h[h.length-1];let wrong=h.filter(x=>!x.correct).length;return wrong*5+(last.correct?0:8)+(last.quality==='uncertain'?4:0)+(last.quality==='again'?6:0)-Math.min(4,h.length)}

