function selectedQuestions(mode,cat){return QUESTIONS.filter(q=>!q.provisional&&!q.void).filter(q=>cat==='all'||cat===q.cat).filter(q=>mode==='new'?!recentOf(q.id):mode==='due'?isDue(q):mode==='wrong'?everWrong(q):true)}
function roundRobin(list,limit){let groups={};for(let q of shuffle(list)){(groups[q.cat]??=[]).push(q)}let out=[];while(out.length<limit){let keys=shuffle(Object.keys(groups).filter(x=>groups[x].length));if(!keys.length)break;for(let k of keys){if(out.length>=limit)break;out.push(groups[k].shift())}}return out}
function queue(mode,cat){let pool=selectedQuestions(mode,cat);if(!pool.length)return [];if(mode==='diagnostic')return roundRobin(pool,10).map(q=>q.id);if(mode==='new')return roundRobin(pool,10).map(q=>q.id);if(mode==='due'||mode==='wrong')return pool.sort((a,b)=>score(b)-score(a)).slice(0,10).map(q=>q.id);if(mode==='all')return shuffle(pool).slice(0,10).map(q=>q.id);
let due=pool.filter(isDue).sort((a,b)=>(state.schedule[a.id].next||'').localeCompare(state.schedule[b.id].next||''));let newItems=roundRobin(pool.filter(q=>!recentOf(q.id)),10);let weak=pool.filter(q=>recentOf(q.id)&&!isDue(q)&&!mastered(q)).sort((a,b)=>score(b)-score(a));let rest=shuffle(pool.filter(q=>!due.includes(q)&&!newItems.includes(q)&&!weak.includes(q)));
return [...new Set([...due,...newItems,...weak,...rest].map(q=>q.id))].slice(0,10)}
function lessonNote(){const due=QUESTIONS.filter(q=>!q.provisional&&!q.void&&isDue(q)),unseen=QUESTIONS.filter(q=>!q.provisional&&!q.void&&!recentOf(q.id));let bycat=DOMAINS.filter(c=>QUESTIONS.some(q=>q.cat===c)).map(c=>({c,wrong:state.history.filter(h=>BYID[h.id].cat===c&&!h.correct).length,attempt:state.history.filter(h=>BYID[h.id].cat===c).length})).filter(x=>x.attempt);bycat.sort((a,b)=>b.wrong/(b.attempt||1)-a.wrong/(a.attempt||1));if(due.length)return '最優先は復習日になった'+due.length+'問です。先に思い出す練習をし、その後で未回答を進めましょう。';if(unseen.length)return 'まだ未回答が'+unseen.length+'問あります。今日は新しい分野も交ぜて10問取り組みましょう。';if(bycat.length&&bycat[0].wrong)return '弱点候補は「'+bycat[0].c+'」です。間違えた理由を確認してから別の問題で再挑戦しましょう。';return '公式過去問の確認が進んでいます。復習日を守り、別の日にも理由を説明できるか確かめましょう。'}

