function tutorItems(){let pool=QUESTIONS.filter(q=>isWeak(recentOf(q.id)));
 return pool.sort((a,b)=>{
  let aa=recentOf(a.id),bb=recentOf(b.id);
  const p=x=> (!x.correct?30:0)+(x.quality==='again'?20:x.quality==='uncertain'?8:0)+(x.reason==='guess'?4:0);
  let da=state.lessonSchedule[a.id]?.next||'',db=state.lessonSchedule[b.id]?.next||'';
  let ad=da!==''&&da>localDate(),bd=db!==''&&db>localDate();
  return Number(ad)-Number(bd)||p(bb)-p(aa)||a.id.localeCompare(b.id)
 })}
