function endSession(){let events=session.events,good=events.filter(x=>x.correct);$('play').classList.add('hidden');$('sessionEnd').classList.remove('hidden');$('sessionBar').style.width='100%';let wrong=events.filter(x=>!x.correct);let wrongcats=[...new Set(wrong.map(x=>BYID[x.id].cat))];const dateCount=events.filter(x=>x.quality==='solid').length;$('sessionSummary').textContent='回答 '+events.length+'問 ／ 正答 '+good.length+'問（'+(events.length?Math.round(100*good.length/events.length):0)+'%）。理由まで説明できる：'+dateCount+'問。'+(wrongcats.length?' 要補強分野：'+wrongcats.join('、')+'。':' 次の復習予定日にも確認しましょう。');session=null;current=null;update();$('sessionEnd').scrollIntoView({behavior:'smooth',block:'start'})}
function renderCategories(){let root=$('categoryGrid');root.innerHTML='';for(let c of DOMAINS){let qq=QUESTIONS.filter(x=>!x.provisional&&!x.void&&x.cat===c);let seen=qq.filter(x=>recentOf(x.id));let history=state.history.filter(x=>BYID[x.id]?.cat===c);let attempted=history.length,correct=history.filter(x=>x.correct).length;let div=document.createElement('div');div.className='group'+(!qq.length?' missing':'');let title=document.createElement('strong');title.textContent=c;div.append(title);let sm=document.createElement('small');sm.textContent=qq.length?('収録 '+qq.length+'問｜着手 '+seen.length+'問｜累計正答率 '+(attempted?Math.round(100*correct/attempted)+'%':'—')+'｜定着確認 '+qq.filter(mastered).length+'問'):'現在の演習問題には未収録';div.append(sm);let bar=document.createElement('div');bar.className='bar';let fill=document.createElement('div');fill.className='fill';fill.style.width=qq.length?(100*seen.length/qq.length)+'%':'0%';bar.append(fill);div.append(bar);if(qq.length){let b=document.createElement('button');b.className='tiny';b.textContent='この分野を演習';b.onclick=()=>{ $('studyCat').value=c;$('studyMode').value='all';begin('all',c)};div.append(b)}root.append(div)}}
function renderHistory(){let due=QUESTIONS.filter(q=>state.schedule[q.id]).sort((a,b)=>state.schedule[a.id].next.localeCompare(state.schedule[b.id].next)).slice(0,8);let el=$('reviewList');el.innerHTML='';let heading=document.createElement('strong');heading.textContent='次の復習予定';el.append(heading);let p=document.createElement('p');p.className='caption';p.textContent=due.length?due.map(q=>q.id+'：'+state.schedule[q.id].next+(isDue(q)?'（今日まで）':'')).join(' ／ '):'まだ復習予定はありません。初回演習から作成されます。';el.append(p);let r=$('recent');r.innerHTML='';let h=document.createElement('strong');h.textContent='最近の解答';r.append(h);let a=document.createElement('p');a.className='caption';a.textContent=state.history.length?state.history.slice(-8).reverse().map(v=>dayOf(v.at)+' '+v.id+' '+(v.correct?'○':'×')+' '+({solid:'説明できる',uncertain:'不安',again:'要補強'}[v.quality]||'')).join(' ／ '):'まだ解答履歴がありません。';r.append(a)}
function exportLog(){let data={format:'pt-study-v17',exported:new Date().toISOString(),questionSet:'official-744-knowledge-core-yearly-figures-v42',originalHistory:state.originalHistory,originalSchedule:state.originalSchedule,history:state.history,schedule:state.schedule,lessonHistory:state.lessonHistory,lessonSchedule:state.lessonSchedule,notes:state.notes,knowledge:state.knowledge,yearProgress:state.yearProgress,transferHistory:state.transferHistory};let blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});let u=URL.createObjectURL(blob);let a=document.createElement('a');a.href=u;a.download='PT国家試験_学習記録_'+localDate()+'.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),500)}
async function importLog(file){if(!file)return;try{if(file.size>4*1024*1024)throw Error('ファイルが大きすぎます');let obj=JSON.parse(await file.text());if(!Array.isArray(obj.history)||!obj.schedule||typeof obj.schedule!=='object')throw Error('データ形式が違います');if(!confirm('現在の学習記録を読み込むファイルの内容で置き換えますか？ 先に現在の記録を書き出しておくと安全です。'))return;rehydrate(obj);save();update();alert('学習記録を読み込みました（公式過去問の記録を反映しました）')}catch(e){alert('読み込めませんでした：'+e.message)}}

for(let c of ['all',...DOMAINS.filter(x=>QUESTIONS.some(q=>q.cat===x))]){let option=document.createElement('option');option.value=c;option.textContent=c==='all'?'全収録分野':c;$('studyCat').append(option)}
load();update();pastInit();$('studyMode').onchange=update;$('studyCat').onchange=update;$('suggestStart').onclick=()=>begin('daily','all');$('start').onclick=()=>begin();$('answer').onclick=answer;$('skip').onclick=skip;$('continue').onclick=next;$('againButton').onclick=()=>begin('daily','all');$('goStats').onclick=()=>$('categories').scrollIntoView({behavior:'smooth'});$('qualityBtns').querySelectorAll('button').forEach(b=>b.onclick=()=>grade(b.dataset.grade));$('reasonBtns').querySelectorAll('button').forEach(b=>b.onclick=()=>reason(b.dataset.reason));$('exportLog').onclick=exportLog;$('importLog').onclick=()=>$('logFile').click();$('logFile').onchange=e=>importLog(e.target.files?.[0]);$('tutorReveal').onclick=()=>{tutorShown=true;renderTutor()};$('tutorNext').onclick=nextTutor;$('tutorPractice').onclick=practiceTutor;$('tutorMemo').onchange=()=>{if(tutorId){state.notes[tutorId]=$('tutorMemo').value.slice(0,500);save()}};document.querySelectorAll('[data-tgrade]').forEach(b=>b.onclick=()=>gradeTutor(b.dataset.tgrade));$('resetLog').onclick=()=>{if(confirm('保存された学習履歴を消去しますか？ 書き出し済みでないデータは戻せません。')){state.history=[];state.schedule={};state.lessonHistory=[];state.lessonSchedule={};state.notes={};state.knowledge=cleanKnowledge({});state.transferHistory=[];state.originalHistory=[];state.originalSchedule={};state.yearProgress={};tutorId=null;save();update();$('play').classList.add('hidden');$('sessionEnd').classList.add('hidden');session=null}};

// 画面導線と学習記録の処理を保持。公式問題数と知識リンクを更新。
const VIEWS={learn:['dashboard','studyAdvanced','play','sessionEnd'],year:['yearBrowser'],related:['pastNavigator'],review:['yearReturnPanel','tutor','knowledgeBook','categoryWrap','reviewHistoryWrap','backupWrap']};
function showView(name,scroll=true){
  if(!VIEWS[name])name='learn';
  for(const [view,ids] of Object.entries(VIEWS))for(const id of ids){const el=document.getElementById(id);if(el)el.classList.toggle('view-hidden',view!==name)}
  document.querySelectorAll('.app-tabs .tab').forEach(b=>{const on=b.dataset.view===name;b.classList.toggle('active',on);b.setAttribute('aria-pressed',on?'true':'false')});
  if(scroll)window.scrollTo({top:0,behavior:'instant'});
}
document.querySelectorAll('.app-tabs .tab').forEach(b=>b.addEventListener('click',()=>showView(b.dataset.view)));
const previousShow=show;
show=function(...args){for(const id of ['rationaleDetails','relatedDetails','reasonDetails','knowledgeFromQuestion']){const d=$(id);if(d)d.open=false}return previousShow(...args)};
const previousBegin=begin;
begin=function(...args){showView('learn',false);return previousBegin(...args)};
const previousBeginOne=beginOne;
beginOne=function(...args){showView('learn',false);return previousBeginOne(...args)};
$('goStats').onclick=()=>{showView('review',false);$('categoryWrap').open=true;$('categories').scrollIntoView({behavior:'smooth',block:'start'})};
showView('learn',false);

