const KNOWLEDGE_QMAP={};
for(const t of KNOWLEDGE_TOPICS)for(const n of t.nodes)for(const id of n.q)(KNOWLEDGE_QMAP[id]??=[]).push(t.id);
let activeKnowledgeTopic='endocrine';
let knowledgeAutoCount=0;
function knowledgeFallback(id){const q=BYID[id];if(!q)return null;return {id:'question:'+id,title:'問題から広げる：'+id,lead:'公式過去問の設問から、わからなかった理由を追いかけて自分の知識を積み上げます。',basis:'起点の公式問題文・正答は収録済み。ただし追加メモの医学的正しさは自動検証しません。',refs:[],nodes:[{id:'base',name:'この問題で何を学ぶ？',chain:[q.stem,'公式採点上の正答：'+formatAcceptedAnswers(q)+(q.acceptedKeys?'（別解あり）':''),'解説の要点：'+q.why],q:[id],ask:'なぜこの正答になる？ 他の選択肢が違う理由を説明できる？'}]}}
function knowledgeTopicList(){const list=[...KNOWLEDGE_TOPICS];const qids=new Set(Object.keys(state.knowledge?.branches||{}).filter(x=>x.startsWith('question:')));for(const key of Object.keys(state.knowledge?.notes||{})){const part=key.split('|')[0];if(part.startsWith('question:'))qids.add(part)}for(const id of qids){const qid=id.slice(9);const t=knowledgeFallback(qid);if(t)list.push(t)}return list}
function countKnowledge(){const k=state.knowledge||{};return Object.keys(k.states||{}).length+Object.keys(k.notes||{}).length+Object.values(k.branches||{}).reduce((n,x)=>n+x.length,0)}
function knowledgeEnsure(){if(!state.knowledge)state.knowledge=cleanKnowledge({});return state.knowledge}
function knowledgeNodeKey(tid,nid){return tid+'|'+nid}
function knowledgeNodelink(qid){const b=document.createElement('button');b.className='tiny secondary';b.textContent=qid+' を解く';b.onclick=()=>beginOne(qid);return b}
function showKnowledge(topicid,focus=''){activeKnowledgeTopic=topicid;knowledgeEnsure();const t=KNOWLEDGE_BYID[topicid]||knowledgeFallback(topicid.startsWith('question:')?topicid.slice(9):'');if(!t)return;
 const select=$('knowledgeTopic');const opts=knowledgeTopicList();select.replaceChildren();const groups={};for(const item of opts){const dom=item.cat||'自分のメモから';let grp=groups[dom];if(!grp){grp=document.createElement('optgroup');grp.label=dom;groups[dom]=grp;select.append(grp)}const o=document.createElement('option');o.value=item.id;o.textContent=item.title;grp.append(o)}select.value=topicid;
 $('knowledgeLead').textContent='【'+(t.cat||'この問題')+'】 '+t.lead;const root=$('knowledgeNodes');root.replaceChildren();
 for(const node of t.nodes){const key=knowledgeNodeKey(topicid,node.id),box=document.createElement('details');box.className='knowledge-node';box.open=(focus?focus===node.id:node===t.nodes[0]);box.id='knowledge-node-'+topicid.replace(/[^A-Za-z0-9]/g,'_')+'-'+node.id;
 const title=document.createElement('summary');title.textContent=node.name;box.append(title);
 const recall=document.createElement('p');recall.className='knowledge-recall';recall.textContent='まず頭の中で説明してみる：'+node.ask;box.append(recall);
 const reveal=document.createElement('button');reveal.type='button';reveal.className='secondary knowledge-reveal';reveal.textContent='仕組みを表示して答え合わせ';box.append(reveal);
 const graph=document.createElement('div');graph.className='knowledge-chain';graph.hidden=true;node.chain.forEach((step,i)=>{if(i){const arr=document.createElement('div');arr.className='knowledge-arrow';arr.textContent='↓';graph.append(arr)}const st=document.createElement('div');st.className='knowledge-step';st.textContent=step;graph.append(st)});box.append(graph);
 reveal.onclick=()=>{graph.hidden=!graph.hidden;reveal.textContent=graph.hidden?'仕組みを表示して答え合わせ':'仕組みを閉じてもう一度思い出す'};
 const ask=document.createElement('p');ask.className='knowledge-mini';ask.textContent='理由を自分の言葉で説明できたか、下のボタンで記録します。';box.append(ask);
 if(node.q.length){const links=document.createElement('div');links.className='flex';const lab=document.createElement('span');lab.className='knowledge-mini';lab.textContent='関係する公式過去問：';links.append(lab);for(const qid of node.q)if(BYID[qid])links.append(knowledgeNodelink(qid));box.append(links)}
 const actions=document.createElement('div');actions.className='flex';const status=state.knowledge.states[key]?.status;
 for(const [v,l] of [['review','まだ説明できない'],['solid','自分で説明できる']]){const btn=document.createElement('button');btn.className='tiny'+(status===v?' on':'');btn.textContent=l;btn.onclick=()=>{state.knowledge.states[key]={status:v,at:new Date().toISOString()};save();showKnowledge(topicid,node.id)};actions.append(btn)}box.append(actions);
 const note=document.createElement('textarea');note.rows=2;note.placeholder='調べたこと・疑問・間違えた理由を自分の言葉で記録';note.setAttribute('aria-label',node.name+' の自分用ノート');note.value=state.knowledge.notes[key]||'';
 note.addEventListener('change',()=>{state.knowledge.notes[key]=note.value.slice(0,1400);save();updateKnowledgeCount()});box.append(note);
 const caption=document.createElement('p');caption.className='knowledge-mini';caption.textContent='メモは端末内に自動保存（入力欄から離れたとき）。理解度は自己評価であり医学的確認済みの印ではありません。';box.append(caption);root.append(box)}
 const custom=state.knowledge.branches[topicid]||[];for(const item of custom){const div=document.createElement('div');div.className='knowledge-branch';const strong=document.createElement('strong');strong.textContent='自分で追加：'+item.title;const text=document.createElement('p');text.textContent=item.text||'説明はまだ空欄です';const tag=document.createElement('div');tag.className='knowledge-mini';tag.textContent='未検証の個人メモ';const remove=document.createElement('button');remove.className='tiny';remove.textContent='この枝を削除';remove.onclick=()=>{if(confirm('この知識の枝を削除しますか？')){state.knowledge.branches[topicid]=state.knowledge.branches[topicid].filter(x=>x.id!==item.id);save();showKnowledge(topicid)}};div.append(strong,text,tag,remove);root.append(div)}
 const rf=$('knowledgeRefBody');rf.replaceChildren();const basis=document.createElement('p');basis.textContent=t.basis;rf.append(basis);for(const [label,url] of t.refs){const p=document.createElement('p');const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener noreferrer';a.textContent=label;p.append(a);rf.append(p)}
 updateKnowledgeCount();
 if(focus){const target=$('knowledge-node-'+topicid.replace(/[^A-Za-z0-9]/g,'_')+'-'+focus);if(target)target.style.borderColor='#1b978e'}
}
function updateKnowledgeCount(){$('knowledgeCount').textContent='自分の記録 '+countKnowledge()+'件'}
function knowledgeForQuestion(qid){let t=(KNOWLEDGE_QMAP[qid]||[])[0];return t||'question:'+qid}
function drawQuestionKnowledge(){const q=current;if(!q)return;const root=$('knowledgeQuestionEntry');if(!root)return;root.replaceChildren();const t=knowledgeForQuestion(q.id),found=KNOWLEDGE_BYID[t];const p=document.createElement('p');p.className='caption';p.textContent=found?'この問題に関係する知識：'+found.title:'この問題の知識を自分の言葉で記録できます。まだ対応する整理済みテーマはありません。';const b=document.createElement('button');b.className='secondary';b.textContent='知識ノートで理由をたどる';b.onclick=()=>{showView('review',false);showKnowledge(t,found?.nodes.find(n=>n.q.includes(q.id))?.id||'');$('knowledgeBook').scrollIntoView({block:'start',behavior:'smooth'})};root.append(p,b)}
$('knowledgeTopic').onchange=e=>showKnowledge(e.target.value);
$('knowledgeAddBtn').onclick=()=>{const title=$('knowledgeBranchTitle').value.trim(),text=$('knowledgeBranchText').value.trim();if(!title){alert('疑問を入力してください。');return}if(title.length>120||text.length>1400){alert('文字数を減らしてください。');return}const tid=activeKnowledgeTopic;knowledgeEnsure();const arr=state.knowledge.branches[tid]??=[];if(arr.length>=80){alert('このテーマの枝は80件まで保存できます。');return}arr.push({id:'b'+Date.now()+'-'+(++knowledgeAutoCount),title,text,at:new Date().toISOString()});save();$('knowledgeBranchTitle').value='';$('knowledgeBranchText').value='';showKnowledge(tid)};
const priorRehydrateKnowledge=rehydrate;
rehydrate=function(s){priorRehydrateKnowledge(s);if(!state.knowledge)state.knowledge=cleanKnowledge({});showKnowledge(activeKnowledgeTopic)};
const priorResetKnowledge=$('resetLog').onclick;
$('resetLog').onclick=()=>{priorResetKnowledge();showKnowledge('endocrine')};
$('answer').onclick=()=>{answer();if(submitted)drawQuestionKnowledge()};
showKnowledge('endocrine');
